// src/components/Features.js
import React from 'react';
import './Features.css';

const Features = () => {
  return (
    <section className="features" id="features">
      <h2>Our Features</h2>
      <div className="feature-cards">
        <div className="feature-card">
          <h3>Job Listings</h3>
          <p>Find the latest actuarial job openings in your area.</p>
        </div>
        <div className="feature-card">
          <h3>Job Alerts</h3>
          <p>Get notified about new actuarial job opportunities.</p>
        </div>
        <div className="feature-card">
          <h3>Company Profiles</h3>
          <p>Explore detailed company profiles and job requirements.</p>
        </div>
      </div>
    </section>
  );
};

export default Features;
